class Solution {
    public int minFallingPathSum(int[][] grid) {
        int n = grid.length;
        int[][] dp = new int[n][n];
        for (int col = 0; col < n; col++) {
            dp[0][col] = grid[0][col];
        }

        for (int row = 1; row < n; row++) {
            int minCol = -1;
            int secondMinCol = -1;
            for (int col = 0; col < n; col++) {
                if (minCol == -1 || dp[row - 1][col] < dp[row - 1][minCol]) {
                    secondMinCol = minCol;
                    minCol = col;
                } else if (secondMinCol == -1 || dp[row - 1][col] < dp[row - 1][secondMinCol]) {
                    secondMinCol = col;
                }
            }

            for (int col = 0; col < n; col++) {
                int bestPrevious = col == minCol ? dp[row - 1][secondMinCol] : dp[row - 1][minCol];
                dp[row][col] = grid[row][col] + bestPrevious;
            }
        }

        int answer = Integer.MAX_VALUE;
        for (int value : dp[n - 1]) {
            answer = Math.min(answer, value);
        }
        return answer;
    }
}

class Solution {
    public int minFallingPathSum(int[][] grid) {
        int n = grid.length;
        int[] previous = grid[0].clone();

        for (int row = 1; row < n; row++) {
            int[] prefixMin = new int[n];
            int[] suffixMin = new int[n];
            prefixMin[0] = previous[0];
            for (int col = 1; col < n; col++) {
                prefixMin[col] = Math.min(prefixMin[col - 1], previous[col]);
            }
            suffixMin[n - 1] = previous[n - 1];
            for (int col = n - 2; col >= 0; col--) {
                suffixMin[col] = Math.min(suffixMin[col + 1], previous[col]);
            }

            int[] current = new int[n];
            for (int col = 0; col < n; col++) {
                int bestPrevious = Integer.MAX_VALUE;
                if (col > 0) {
                    bestPrevious = Math.min(bestPrevious, prefixMin[col - 1]);
                }
                if (col + 1 < n) {
                    bestPrevious = Math.min(bestPrevious, suffixMin[col + 1]);
                }
                current[col] = grid[row][col] + bestPrevious;
            }
            previous = current;
        }

        int answer = Integer.MAX_VALUE;
        for (int value : previous) {
            answer = Math.min(answer, value);
        }
        return answer;
    }
}

